def block_spectrum(dq, want_L=True):
    H = dq*Hcf + Hee
    res = {}
    for key,(Bfull,d) in blocks.items():
        Hb = Bfull.T @ H @ Bfull
        Lb = Bfull.T @ L2 @ Bfull
        w, v = np.linalg.eigh(Hb)
        levs = []
        for k in range(0,len(w),d):
            vk = v[:,k:k+d]
            # L2 expectation on the cluster
            Lk = np.linalg.eigvalsh(vk.T@Lb@vk)
            levs.append((w[k], Lk))
        res[key]=levs
    return res
